<content>
40: view,text,image,input,textarea,scroll-view,label{box-sizing:border-box;margin:0;padding:0;border:0 solid}
41: image{display:block;max-width:100%}
42: input,textarea{font:inherit;color:inherit;background:transparent;outline:none;border:0 solid}
43: 
44: /* 屏幕容器：页头 72px + 底部操作栏 72px */
45: .screen{min-height:100vh;min-height:100dvh;background:var(--c-bg);padding:calc(72px + var(--status-bar-height,0px)) 0 calc(72px + env(safe-area-inset-bottom));position:relative;margin:auto;max-width:720px;box-sizing:border-box}
46: .form-screen{padding-bottom:calc(72px + env(safe-area-inset-bottom))}
47: 
48: /* 固定页头：归档截图页头高 72px */
49: .app-header{position:fixed;z-index:20;top:var(--status-bar-height,0px);left:0;right:0;margin:0 auto;max-width:720px;height:72px;display:flex;align-items:center;justify-content:center;background:rgba(255,255,255,.96);backdrop-filter:blur(24px);-webkit-backdrop-filter:blur(24px);box-shadow:0 1px 8px #0000000a}
50: .app-header-title{font-size:19px;font-weight:500;line-height:25px}
51: .app-back{position:absolute;left:14px;top:0;height:72px;display:flex;align-items:center}
52: .app-back-glyph{font-family:sans-serif;font-weight:400;font-size:32px;line-height:1}
53: 
54: /* ===== 工作台 ===== */
55: .workspace{display:flex;gap:12px;padding:10px 16px}
56: .workspace-aside{width:80px;display:flex;flex-direction:column;gap:8px;flex:none}
57: .side-tab{height:76px;text-align:center;border-radius:12px;background:var(--c-fill);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;font-size:14px;position:relative}
58: .side-tab-image{width:20px;height:20px}
59: .side-tab.active{background:var(--c-brand-soft);color:#004fd0}
60: .side-tab.active::before{content:'';position:absolute;left:0;top:8px;bottom:8px;width:4px;border-radius:0 9px 9px 0;background:#004fd0}
61: .apps{flex:1;min-width:0}
62: .section-title{height:38px;padding:0 12px;background:var(--c-surface);border-radius:var(--r-ctl);display:flex;align-items:center;justify-content:space-between;box-shadow:var(--shadow-card);font-size:16px;margin-bottom:8px}
63: .section-title-text{font-weight:700}
64: .section-title-count{font-size:13px;color:var(--c-text-2);background:var(--c-fill-strong);padding:2px 8px;border-radius:99px}
65: .app-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}
66: .app-card{height:116px;text-align:center;background:var(--c-surface);border-radius:var(--r-card);box-shadow:var(--shadow-card);display:flex;flex-direction:column;align-items:center;justify-content:center}
67: .icon-well{width:48px;text-align:center;height:48px;border-radius:16px;display:grid;place-items:center;margin-bottom:6px;background:#eff6ffcc}
68: .icon-well-image{width:24px;height:24px}
69: .tone-1{background:#eef2ffcc}
70: .tone-2{background:#f0fdfacc}
71: .tone-3{background:#fffbeacc}
72: .app-card-title{font-size:16px;line-height:20px;font-weight:700}
73: .app-card-sub{font-size:12px;color:var(--c-text-2);line-height:14px}
74: 
75: /* 底部导航 */
76: .bottom-nav{position:fixed;z-index:20;bottom:0;left:0;right:0;margin:0 auto;max-width:720px;height:calc(64px + env(safe-area-inset-bottom));padding-bottom:env(safe-area-inset-bottom);background:rgba(247,249,253,.92);backdrop-filter:blur(24px);-webkit-backdrop-filter:blur(24px);display:flex;justify-content:space-around;box-shadow:0 -2px 12px #0000000a}
77: .bottom-nav-item{width:33%;text-align:center;display:flex;flex-direction:column;align-items:center;justify-content:center;font-size:13px}
78: .bottom-nav-image{width:20px;height:20px;margin-bottom:2px}
79: .bottom-nav-item.selected{color:#004fd0}
80: 
81: /* 表单
82:    归档截图是 1x 设备像素（414×1953），故所有尺寸直接用截图度量值：
83:    内容区左右 14px、卡片宽 358px 内边距 10px、字段 pitch 44px、
84:    标签行高 20px、步进器高 24px、卡片圆角 10px */
85: .form-content{display:flex;flex-direction:column;gap:12px;padding:12px 14px}
86: .form-card{background:var(--c-surface);border-radius:10px;padding:12px 10px;box-shadow:var(--shadow-card);display:flex;flex-direction:column;gap:14px}
87: .field{display:flex;flex-direction:column;gap:4px}
88: .field-label,.upload-label{font-size:15px;line-height:20px;display:block}
89: .field-required{color:#ba1a1a}
90: .field-input,.field-textarea{background:var(--c-fill);border-radius:6px;padding:0 8px;font-size:15px;width:100%;display:block}
91: .field-input{height:40px;line-height:40px;display:flex;align-items:center}
92: /* 输入框中的原生 input 需继承容器尺寸 */
93: .field-input > input{width:100%;height:38px;line-height:38px;display:block;background:transparent;border:0;font-size:15px;color:var(--c-text);padding:0}
94: .field-input > input::placeholder{color:var(--c-text-3)}
95: .field-textarea-wrap{position:relative;background:var(--c-fill);border-radius:6px;padding:8px 8px 20px}
96: .field-textarea-wrap .field-textarea.inner{background:transparent;padding:0;height:76px;min-height:76px;border-radius:0;line-height:20px;font-size:15px}
97: .field-count{position:absolute;right:8px;bottom:3px;font-size:13px;line-height:15px;color:var(--c-text-3)}
98: .date-icon{width:16px;height:16px;flex:none}
99: .field-textarea{height:92px;min-height:92px;line-height:21px;resize:vertical}
100: .field-counter{font-size:13px;color:var(--c-text-2);line-height:16px;text-align:center;display:block}
101: /* 步进器：归档截图中高度 48px 的一半 24px，两侧按钮 44×36 → 22×18 */
102: .stepper{height:40px;border-radius:6px;background:var(--c-fill);padding:4px 6px;display:flex;align-items:center;gap:6px}
103: .stepper-button{width:36px;height:30px;border-radius:6px;background:var(--c-fill-strong);font-size:19px;line-height:1;display:flex;align-items:center;justify-content:center;color:var(--c-text)}
104: .stepper-button.disabled{opacity:.45}
105: .stepper-value{flex:1;text-align:center;color:var(--c-text-3);font-size:16px}
106: .choices{display:flex;gap:8px}
107: .choice{flex:1;text-align:center;background:var(--c-fill);border-radius:6px;height:32px;color:var(--c-text-2);font-size:16px;display:flex;align-items:center;justify-content:center}
108: .choice.chosen{background:var(--c-brand);color:#fff}
109: /* 紧急程度：三档，默认橙色选中，特级为深红 */
110: .choices.levels .choice{height:40px;font-size:16px}
111: .choices.levels .choice.chosen{background:var(--c-orange);color:#fff}
112: .choices.levels .choice.chosen.critical{background:var(--c-critical)}
113: .inspection-section-title{font-size:17px;font-weight:700;line-height:22px;border-left:3px solid #0868e8;padding-left:8px}
114: /* 分区卡片：标题 + 选项 + 数量 + 备注 + 图片凭证 */
115: .sec{margin-bottom:0}
116: .sec-head{display:flex;align-items:center;gap:6px;margin-bottom:10px}
117: .sec-badge{flex:none;min-width:22px;height:19px;padding:0 5px;border-radius:4px;background:var(--c-brand);color:#fff;font-size:13px;line-height:19px;text-align:center;font-weight:700}
118: .sec-name{font-size:17px;font-weight:700;line-height:21px;color:var(--c-text)}
119: .sec-item{display:flex;flex-direction:column;gap:6px;margin-bottom:14px}
120: .sec-item:last-child{margin-bottom:0}
121: .sec-item-label{font-size:14px;line-height:18px;color:var(--c-text-2)}
122: .sec-item-label .req{color:#ba1a1a}
123: /* 设计稿中的两态/多态按钮：白底描边，选中为蓝底 */
124: .seg{display:flex;gap:8px;flex-wrap:wrap}
125: .seg-choice{min-width:64px;flex:1;text-align:center;height:34px;border-radius:6px;border:1px solid var(--c-line);background:#fff;color:var(--c-text-2);font-size:15px;display:flex;align-items:center;justify-content:center;padding:0 6px}
126: .seg-choice.chosen{background:var(--c-brand);border-color:var(--c-brand);color:#fff}
127: /* 备注与图片凭证 */
128: .sec-note{background:var(--c-fill);border-radius:6px;padding:8px;font-size:14px;line-height:18px;color:var(--c-text);min-height:52px;width:100%}
129: .sec-photo{display:flex;align-items:center;gap:8px;margin-top:10px}
130: .sec-photo-label{font-size:13px;color:var(--c-text-3);flex:none}
131: .sec-photo-add{flex:1;height:52px;border-radius:6px;border:1px dashed #c3c8d2;background:#fafbfd;color:var(--c-text-3);font-size:14px;display:flex;align-items:center;justify-content:center;gap:6px}
132: .sec-photo-count{font-size:13px;color:var(--c-text-3);flex:none}
133: 
134: /* 照片：一行三个，等宽三分列（flex-basis 33.33%），不撑满 */
135: .photo-row{display:flex;flex-wrap:wrap;gap:8px}
136: .photo-thumb{flex:0 0 calc((100% - 16px) / 3);width:calc((100% - 16px) / 3);height:104px;border-radius:8px;overflow:hidden;position:relative;box-sizing:border-box}
137: .photo-thumb-image{width:100%;height:100%;object-fit:cover;border-radius:8px;display:block}
138: .photo-upload{flex:0 0 calc((100% - 16px) / 3);width:calc((100% - 16px) / 3);height:104px;border-radius:8px;background:var(--c-fill);color:var(--c-brand);font-size:28px;display:flex;flex-direction:column;align-items:center;justify-content:center;overflow:hidden;box-sizing:border-box}
139: .photo-upload-text{font-size:13px;color:var(--c-text-2);margin-top:4px}
140: .photo-remove{position:absolute;right:4px;top:4px;width:20px;height:20px;border-radius:50%;background:rgba(0,0,0,.55);color:#fff;font-size:15px;line-height:20px;text-align:center}
141: .photo-state{position:absolute;left:0;right:0;bottom:0;padding:2px;font-size:12px;color:#fff;background:rgba(0,0,0,.6);text-align:center}
142: .photo-state.failed{background:#b42318}
143: .photo-caption{position:absolute;left:0;right:0;bottom:0;padding:2px;font-size:12px;color:#fff;background:rgba(0,0,0,.5);text-align:center}
144: .photo-hint{font-size:13px;color:var(--c-text-3);line-height:16px;margin-top:2px;display:block}
145: 
146: /* 底部操作栏 */
147: .action-bar{position:fixed;z-index:20;bottom:0;left:0;right:0;margin:0 auto;max-width:720px;height:calc(72px + env(safe-area-inset-bottom));padding:12px 14px;padding-bottom:calc(12px + env(safe-area-inset-bottom));background:#fffffff0;backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);display:flex;gap:10px;box-shadow:0 -4px 16px #0000000f}
148: .action-button{flex:1;text-align:center;border-radius:6px;background:var(--c-brand);color:#fff;font-size:18px;display:flex;align-items:center;justify-content:center}
149: .action-button.secondary{flex:0 0 110px;background:var(--c-surface);color:var(--c-text);border:1px solid #d7dae0}
150: .action-bar.orange .action-button{background:var(--c-orange);border-radius:12px;font-size:19px;font-weight:700}
151: .action-button.disabled{opacity:.6}
152: /* 详情页底部：单个主按钮占满 */
153: .action-bar.single .action-button{flex:1}
154: .rescue-fab{position:fixed;text-align:center;z-index:12;right:16px;right:max(16px,calc(50% - 344px));bottom:84px;background:var(--c-orange);color:#fff;border-radius:99px;padding:10px 16px;font-size:16px;box-shadow:0 6px 18px #fe9c2d55}
155: .form-alert{position:fixed;z-index:19;left:0;right:0;margin:0 auto;max-width:720px;bottom:84px;padding:10px 14px;background:#fff0ee;color:#b42318;font-size:15px;line-height:19px;border-radius:6px;box-shadow:0 4px 16px #0000001a}
156: .form-alert.success{background:#eaf6f0;color:#16754c}
157: 
